# 02_inn_visualization.R
#
# Xenium inhibitory-neuron subtype visualization | MegaData_v8
# Input: annotated datIN_v8.rds generated by 01_inn_clustering_annotation.R
# LK, October 2026
#
# This script:
# 1. Loads the annotated inhibitory-neuron Seurat object
# 2. Generates UMAPs for clusters, subtypes, ILAE scores and samples
# 3. Generates spatial subtype maps for individual Xenium fields of view
# 4. Plots marker-gene expression across broad inhibitory-neuron subtypes
# 5. Generates supplementary spatial maps and regional subtype proportions
#
# Default Seurat/ggplot2 colors are used throughout; no palette files are required.

### Setup ----------------------------------------------------------------------

suppressPackageStartupMessages({
        library(Seurat)
        library(dplyr)
        library(ggplot2)
        library(patchwork)
        library(conflicted)
        conflicts_prefer('base','setdiff')
})

### User-editable configuration -------------------------------------------------

# Update paths to match the local project structure.
cfg <- list(
        dat_rds = "path/to/directory/data/MegaData_v8_annotated_final.rds",
        datIN_rds = "path/to/directory/data/datIN_v8.rds",
        region_metadata_rds = "path/to/directory/data/megadata_metadata_md_v8.rds",
        output_dir_plots = "path/to/directory/plots/InN_v8"
)

if (!file.exists(cfg$datIN_rds)) stop("Input file not found: ", cfg$datIN_rds)
dir.create(file.path(cfg$output_dir_plots, "ImageDimPlot"), recursive = TRUE, showWarnings = FALSE)

### COLOR PALETTES #############################################################
# palette for sample groups (ILAE_score)
pal_ILAE_score <- c("P" = "#C67BFF", "0" = "#F8766C", "1" = "#7BAD00",
                    "2" = "#00C0C5", "3" = "#E69F00")


pal_Sample <- c(
        "D9"   = "#E69F00",
        "L15"  = "#56B4E9",
        "L14"  = "#009E73",
        "D11"  = "#F0E442",
        "E015" = "#0072B2",
        "L1"   = "#D55E00",
        "L3"   = "#CC79A7",
        "L2"   = "#666666",
        "L21"  = "#AD7700",
        "L20"  = "#1C91D4",
        "E008" = "#007756",
        "M70"  = "#D5C711",
        "D13"  = "#005685",
        "P28"  = "#A04700",
        "B1"   = "#B14380",
        "L18"  = "#4D4D4D",
        "C1"   = "#FFBE2D",
        "F1"   = "#80C7EF",
        "P71"  = "#00F6B3",
        "P51"  = "#F4EB71",
        "C2"   = "#06A5FF",
        "J1"   = "#FF8320",
        "I1"   = "#D99BBD",
        "D12"  = "#8C8C8C",
        "L10"  = "#FFCB57",
        "P60"  = "#9AD2F2",
        "H1"   = "#2CFFC6",
        "L5"   = "#F6EF8E",
        "D8"   = "#38B7FF",
        "D14"  = "#FF9B4D",
        "M56"  = "#E0AFCA"
)

### Load annotated data ------------------------------------------
if (!exists("datIN", envir = .GlobalEnv, inherits = FALSE)) {
        datIN <- readRDS(cfg$datIN_rds)
        message("Loaded datIN from: ", cfg$datIN_rds)
} else {
        message("Using datIN already in the environment.")
}

if (!exists("dat", envir = .GlobalEnv, inherits = FALSE)) {
        dat <- readRDS(cfg$dat_rds)
        message("Loaded dat from: ", cfg$dat_rds)
} else {
        message("Using dat already in the environment.")
}

required_meta <- c("seurat_clusters", "fine_subtype_InhN", "broad_subtype_InhN",
                   "ILAE_score", "orig.ident", "region_md")

missing_meta <- setdiff(required_meta, colnames(datIN@meta.data))

if (length(missing_meta)) stop("Missing metadata in datIN: ", paste(missing_meta, collapse = ", "))

required_meta_dat <- c("orig.ident", "region_md")

missing_meta_dat <- setdiff(required_meta_dat, colnames(dat@meta.data))

if (length(missing_meta_dat)) stop("Missing metadata in dat: ", paste(missing_meta_dat, collapse = ", "))

### Define plotting order -------------------------------------------------------

# Fix the ILAE group order in legends; colors are assigned automatically.
datIN$ILAE_score <- factor(as.character(datIN$ILAE_score), levels = c("P", "0", "1", "2", "3"))

# Retain the original sample order, appending any additional samples rather than
# converting them to NA. This affects legend order, not which cells are included.
sample_order <- c("L10", "L5", "M70", "P28", "P60", "P71", "P51", "M56",
                  "B1", "F1", "H1", "I1", "J1", "L20", "D11", "D8",
                  "C1", "C2", "E008", "L14", "L15", "L18",
                  "L1", "L21", "L3", "D12", "D13", "E015", "L2", "D9", "D14")

extra_samples <- setdiff(unique(as.character(datIN$orig.ident)), sample_order)

datIN$orig.ident <- factor(as.character(datIN$orig.ident), levels = c(sample_order, extra_samples))

# Broad subtype order is used in the marker-gene dot plot.
broad_order <- c("SST", "PV", "C1QL1", "LAMP5.MGE", "LAMP5.CGE",
                 "CXCL14", "HTR3A", "VIP", "Cajal")

### UMAPs of clusters and inhibitory-neuron subtypes ----------------------------

# Compare unsupervised clusters with fine/broad annotations and sample metadata.
# Plots are displayed; uncomment ggsave() below if you want a PDF copy.
Idents(datIN) <- datIN$seurat_clusters

DimPlot(datIN, shuffle = TRUE, label = TRUE) +
        coord_fixed() + theme(legend.position = "right")
DimPlot(datIN, group.by = "broad_subtype_InhN", shuffle = TRUE,label = TRUE, repel = TRUE) +
        coord_fixed() + theme(legend.position = "right")
DimPlot(datIN, group.by = "fine_subtype_InhN", shuffle = TRUE,label = FALSE) +
        coord_fixed() + theme(legend.position = "right")
DimPlot(datIN, group.by = "ILAE_score", shuffle = TRUE,cols = pal_ILAE_score) + 
        coord_fixed() + theme(legend.position = "right")
DimPlot(datIN, group.by = "orig.ident", shuffle = TRUE,cols = pal_Sample) + 
        coord_fixed() + theme(legend.position = "right")

### Spatial maps of broad inhibitory-neuron subtypes ---------------------------
# Plot the broad subtype annotations for each available Xenium field of view.
# Each sample is saved as an individual PDF; missing FOVs are skipped.
available_fovs <- names(datIN@images)
for (fov in c(sample_order, extra_samples)) {
        if (!fov %in% available_fovs) {
                message("Skipping FOV absent from datIN: ", fov)
                next
        }
        spatial_plot <- ImageDimPlot(datIN, fov = fov, group.by = "broad_subtype_InhN",
                                     size = 2, border.size = NA, axes = FALSE,
                                     dark.background = FALSE) +
                theme(panel.grid.major = element_blank(), panel.grid.minor = element_blank())
        ggsave(file.path(cfg$output_dir_plots, "ImageDimPlot", paste0(fov, "_ImageDimPlot.pdf")),
               plot = spatial_plot, width = 10, height = 10)
}

### Marker-gene dot plot --------------------------------------------------------

# Display canonical inhibitory-neuron markers across broad subtype annotations.
datIN$broad_subtype_InhN <- factor(as.character(datIN$broad_subtype_InhN), levels = broad_order)

DefaultAssay(datIN) <- "SCT"

genes_to_plot <- c("SST", "NPY", "PVALB", "LHX6", "LAMP5", "KIT", "CXCL14", "CCK", "VIP")

dotplot <- DotPlot(datIN, features = genes_to_plot, group.by = "broad_subtype_InhN") +
        theme(legend.position = "top", legend.justification = "center")

print(dotplot)

### Proportions of broad subtypes in each anatomical regions --------------------

# Region metadata is computed in domain analysis and added there to the MegaData.
# MegaData_annotated_v8 from GEO already contains the domain labels so we will not need 
# to add them again but use them here
# The denominator is all cells of a given subtype across atlas regions, not all
# cells in a region. Each stacked bar therefore sums to 100% for that subtype.

region_order <- c("GCL", "CA2_CA4", "CA1", "SUB", "GABA", "ML", "SL.SR.SLM",
                  "pia", "vascular", "void", "WM")

prop_table <- datIN@meta.data %>%
        filter(!is.na(broad_subtype_InhN), !is.na(region_md)) %>%
        dplyr::count(subtype = broad_subtype_InhN, region_md, name = "n") %>%
        group_by(subtype) %>%
        mutate(proportion = n / sum(n)) %>%
        ungroup() %>%
        mutate(subtype = factor(as.character(subtype),
                                levels = c(broad_order,
                                           setdiff(unique(as.character(subtype)), broad_order))),
               region_md = factor(region_md,
                                  levels = c(region_order,
                                             setdiff(unique(as.character(region_md)), region_order))))

p_region <- ggplot(prop_table, aes(x = subtype, y = proportion, fill = region_md)) +
        geom_col(width = 0.8) +
        scale_y_continuous(labels = scales::percent_format(accuracy = 1)) +
        labs(x = "InN cell type", y = "Proportion in atlas region", fill = "Atlas region") +
        theme_classic(base_size = 8) +
        theme(axis.text.x = element_text(angle = 45, hjust = 1))

p_region


### Function: Regional InN subtype proportions and ILAE comparisons ------------

# The all-cell denominator comes from dat, already loaded above.
# Sample-region combinations with no subtype cells are included as true zeros.
plot_regional_cell_density <- function(seurat_obj, all_cells_obj, celltype_col,
                                       region_col = "region_md", sample_col = "orig.ident", group_col = "ILAE_score",
                                       group_levels = c("P", "0", "1", "2", "3"),
                                       regions_use = NULL, celltypes_use = NULL,
                                       output_dir = "plots/Density_by_region",
                                       pdf_width = 10, pdf_height = 8, ncol = 3,
                                       kw_p_cutoff = 0.05, dunn_p_cutoff = 0.05) {
        
        ##Check arguments, metadata columns and output directory
        required_cols <- c(celltype_col, region_col, sample_col, group_col)
        missing_cols <- setdiff(required_cols, colnames(seurat_obj@meta.data))
        if (length(missing_cols) > 0) stop("Missing metadata columns in seurat_obj: ", paste(missing_cols, collapse = ", "))
        missing_all_cols <- setdiff(c(region_col, sample_col), colnames(all_cells_obj@meta.data))
        if (length(missing_all_cols) > 0) stop("Missing metadata columns in all_cells_obj: ",
                                               paste(missing_all_cols, collapse = ", "))
        if (!dir.exists(output_dir)) dir.create(output_dir, recursive = TRUE)
        
        ##Prepare metadata used for subtype counts
        metadata <- seurat_obj@meta.data %>%
                transmute(orig.ident = as.character(.data[[sample_col]]),
                          region_md = as.character(.data[[region_col]]),
                          celltype = as.character(.data[[celltype_col]]),
                          ILAE_score = as.character(.data[[group_col]])) %>%
                filter(!is.na(orig.ident), !is.na(region_md), !is.na(celltype), !is.na(ILAE_score))
        
        if (!is.null(regions_use)) metadata <- metadata %>% filter(region_md %in% regions_use)
        if (!is.null(celltypes_use)) metadata <- metadata %>% filter(celltype %in% celltypes_use)
        if (nrow(metadata) == 0) stop("No cells remain after filtering regions_use and/or celltypes_use.")
        
        ##Count all cells per sample and region from all_cells_obj
        total_cells <- all_cells_obj@meta.data %>%
                transmute(orig.ident = as.character(.data[[sample_col]]),
                          region_md = as.character(.data[[region_col]])) %>%
                filter(!is.na(orig.ident), !is.na(region_md)) %>%
                count(orig.ident, region_md, name = "n_total_cells")
        
        if (!is.null(regions_use)) total_cells <- total_cells %>% filter(region_md %in% regions_use)
        
        ##Prepare sample-level ILAE information
        sample_metadata <- seurat_obj@meta.data %>%
                transmute(orig.ident = as.character(.data[[sample_col]]),
                          ILAE_score = as.character(.data[[group_col]])) %>%
                filter(!is.na(orig.ident), !is.na(ILAE_score)) %>%
                distinct()
        
        duplicate_groups <- sample_metadata %>%
                count(orig.ident) %>%
                filter(n > 1)
        if (nrow(duplicate_groups) > 0) stop("Some samples have more than one ", group_col, " value.")
        
        sample_metadata <- sample_metadata %>%
                mutate(ILAE_score = factor(ILAE_score, levels = group_levels))
        
        ##Count subtype cells per sample and region
        cell_counts <- metadata %>%
                count(orig.ident, region_md, celltype, name = "n_cells")
        
        ##Check that subtype observations have a corresponding all-cell denominator
        missing_regions <- cell_counts %>%
                anti_join(total_cells, by = c("orig.ident", "region_md")) %>%
                distinct(orig.ident, region_md)
        if (nrow(missing_regions) > 0) {
                print(missing_regions)
                warning("Some subtype sample-region combinations are missing from dat and will be excluded.")
        }
        
        ##Determine selected cell types and regions
        celltypes <- if (is.null(celltypes_use)) sort(unique(metadata$celltype)) else
                celltypes_use[celltypes_use %in% unique(metadata$celltype)]
        regions <- if (is.null(regions_use)) sort(unique(metadata$region_md)) else
                regions_use[regions_use %in% unique(metadata$region_md)]
        
        ##Create proportion table including true zero subtype observations
        density_region <- total_cells %>%
                filter(region_md %in% regions) %>%
                tidyr::crossing(celltype = celltypes) %>%
                left_join(cell_counts, by = c("orig.ident", "region_md", "celltype")) %>%
                mutate(n_cells = tidyr::replace_na(n_cells, 0L),
                       fraction_all_cells = if_else(!is.na(n_total_cells) & n_total_cells > 0,
                                                    n_cells / n_total_cells, NA_real_)) %>%
                left_join(sample_metadata, by = "orig.ident") %>%
                filter(!is.na(ILAE_score))
        
        ##Response is the subtype fraction among all cells in each sample-region
        response_var <- "fraction_all_cells"
        y_label <- "Fraction of all cells"
        
        ##Kruskal-Wallis tests with global BH correction across all selected cell type-region tests
        kw_results <- density_region %>%
                group_by(celltype, region_md) %>%
                group_modify(~{
                        dat_test <- .x %>% filter(!is.na(.data[[response_var]]))
                        if (n_distinct(dat_test$ILAE_score) < 2 || n_distinct(dat_test[[response_var]]) < 2) {
                                return(tibble(n_groups = n_distinct(dat_test$ILAE_score), p = NA_real_))
                        }
                        test_formula <- reformulate("ILAE_score", response = response_var)
                        tibble(n_groups = n_distinct(dat_test$ILAE_score),
                               p = tryCatch(kruskal.test(test_formula, data = dat_test)$p.value,
                                            error = function(e) NA_real_))
                }) %>%
                ungroup() %>%
                mutate(p_adj = p.adjust(p, method = "BH"),
                       significance = case_when(p_adj < 0.0001 ~ "****",
                                                p_adj < 0.001 ~ "***",
                                                p_adj < 0.01 ~ "**",
                                                p_adj < 0.05 ~ "*",
                                                TRUE ~ "ns"))
        
        ##Dunn posthoc tests with global BH correction across all selected pairwise comparisons
        dunn_results <- density_region %>%
                group_by(celltype, region_md) %>%
                group_modify(~{
                        dat_test <- .x %>% filter(!is.na(.data[[response_var]]))
                        if (n_distinct(dat_test$ILAE_score) < 2 || n_distinct(dat_test[[response_var]]) < 2) return(tibble(comparison = character(), z = numeric(), p = numeric()))
                        test_formula <- reformulate("ILAE_score", response = response_var)
                        out <- tryCatch(FSA::dunnTest(test_formula, data = dat_test, method = "none")$res,
                                        error = function(e) NULL)
                        if (is.null(out)) return(tibble(comparison = character(), z = numeric(), p = numeric()))
                        tibble(comparison = out$Comparison, z = out$Z, p = out$P.unadj)
                }) %>%
                ungroup() %>%
                mutate(p_adj = p.adjust(p, method = "BH"),
                       significance = case_when(p_adj < 0.0001 ~ "****",
                                                p_adj < 0.001 ~ "***",
                                                p_adj < 0.01 ~ "**",
                                                p_adj < 0.05 ~ "*",
                                                TRUE ~ "ns")) %>%
                left_join(kw_results %>% select(celltype, region_md, kw_p_adj = p_adj),
                          by = c("celltype", "region_md"))
        
        ##Create region plots and save one PDF per subtype
        plot_list <- list()
        
        for (ct in celltypes) {
                ct_data <- density_region %>% filter(celltype == ct)
                region_plots <- list()
                
                for (reg in regions) {
                        plot_df <- ct_data %>%
                                filter(region_md == reg, !is.na(.data[[response_var]]))
                        if (nrow(plot_df) == 0) next
                        
                        ##Get Kruskal-Wallis and significant posthoc results for subtitle
                        kw_plot <- kw_results %>%
                                filter(celltype == ct, region_md == reg)
                        
                        dunn_plot <- dunn_results %>%
                                filter(celltype == ct, region_md == reg,
                                       kw_p_adj < kw_p_cutoff, p_adj < dunn_p_cutoff) %>%
                                arrange(p_adj)
                        
                        kw_text <- if (nrow(kw_plot) == 0 || is.na(kw_plot$p_adj)) {
                                "KW adj. p = NA"
                        } else {
                                paste0("KW adj. p = ", format.pval(kw_plot$p_adj, digits = 2, eps = 0.001))
                        }
                        
                        if (nrow(dunn_plot) > 0) {
                                dunn_text <- paste0(dunn_plot$comparison, " ",
                                                    format.pval(dunn_plot$p_adj, digits = 2, eps = 0.001),
                                                    collapse = "; ")
                                subtitle_text <- paste0(kw_text, "\nDunn adj. p: ", dunn_text)
                        } else {
                                subtitle_text <- paste0(kw_text, "\nDunn: no significant comparisons")
                        }
                        
                        ##Determine data-dependent y-axis
                        y_max <- max(plot_df[[response_var]], na.rm = TRUE)
                        if (!is.finite(y_max) || y_max == 0) y_max <- 0.01
                        plot_y_min <- -y_max * 0.03
                        plot_y_max <- y_max * 1.08
                        
                        ##Create plot
                        p <- ggplot(plot_df, aes(x = ILAE_score, y = .data[[response_var]])) +
                                geom_boxplot(aes(fill = ILAE_score), outlier.shape = NA, width = 0.6, alpha = 0.7) +
                                geom_jitter(color = 'black', width = 0.15, size = 1.5, alpha = 0.8) +
                                labs(title = reg, subtitle = subtitle_text, x = "ILAE score", y = y_label) +
                                theme_classic(base_size = 9) +
                                theme(axis.text.x = element_text(angle = 45, hjust = 1),
                                      plot.title = element_text(size = 10),
                                      plot.subtitle = element_text(size = 7),
                                      legend.position = "none")
                        
                        ##Display proportions as percentages with independently scaled y-axes
                        p <- p +
                                scale_y_continuous(breaks = scales::pretty_breaks(n = 5),
                                                   labels = scales::label_percent(accuracy = 0.1),
                                                   expand = expansion(mult = c(0, 0))) +
                                coord_cartesian(ylim = c(plot_y_min, plot_y_max))
                        
                        region_plots[[reg]] <- p
                }
                
                if (length(region_plots) == 0) next
                ##Combine independent region plots
                combined_plot <- patchwork::wrap_plots(region_plots, ncol = ncol) +
                        patchwork::plot_annotation(title = paste0(ct, " - fraction of all cells"),
                                                   theme = theme(plot.title = element_text(size = 12)))
                
                plot_list[[ct]] <- combined_plot
                safe_name <- gsub("[^A-Za-z0-9_-]", "_", ct)
                
                ggsave(file.path(output_dir, paste0("Regional_fraction_all_cells_", safe_name, ".pdf")),
                       combined_plot, width = pdf_width, height = pdf_height)
        }
        
        ##Return abundance data, statistics and plots
        return(list(data = density_region,
                    kruskal = kw_results,
                    dunn = dunn_results,
                    plots = plot_list,
                    missing_regions = missing_regions))
}

### Broad InN subtype proportions by region ------------------------------------
#test only MGE InN subtypes in their appropriate layers
test_path<-here('plots','InN_v8_github')
density_broad_MGE <- plot_regional_cell_density(
        seurat_obj = datIN,
        all_cells_obj = dat,
        celltype_col = "broad_subtype_InhN",
        celltypes_use = c('LAMP5.MGE','SST', 'PV'),
        regions_use = c("GCL", "CA2_CA4", "CA1", "SUB", "GABA"),
        output_dir = file.path(test_path, "proportion_by_region", "broad_subtype_InhN_MGE"),
        pdf_width = 12, pdf_height = 6, ncol = 5
)

print(density_broad_MGE$dunn %>% filter(p_adj < 0.05))

#test only CGE InN subtypes in their appropriate layers
density_broad_CGE <- plot_regional_cell_density(
        seurat_obj = datIN,
        all_cells_obj = dat,
        celltype_col = "broad_subtype_InhN",
        celltypes_use = c('VIP','LAMP5.CGE', 'CXCL14', 'HTR3A'),
        regions_use = c("SL.SR.SLM", "ML"),
        output_dir = file.path(cfg$output_dir_plots, "proportion_by_region", "broad_subtype_InhN_CGE"),
        pdf_width = 12, pdf_height = 6, ncol = 5
)

print(density_broad_CGE$dunn %>% filter(p_adj < 0.05))
